pub type Temperature = Float64
  invariant: this >= -273.15;  // Absolute zero

fn heat(temp: &mut Temperature, delta: Float64)
  requires: delta >= 0.0;
  ensures: temp == temp@pre + delta;
{
  temp = temp + delta;
}

fn main() -> Int {
  var t: Temperature = 20.0;
  heat(&mut t, 30.0);
  return t as Int;
}
